package com.eventsphere.common;
import java.time.LocalDateTime;
public class ApiResponse<T>{private boolean success;private String message;private T data;private LocalDateTime timestamp=LocalDateTime.now(); public ApiResponse(){} public ApiResponse(boolean s,String m,T d){success=s;message=m;data=d;} public static <T> ApiResponse<T> success(String m,T d){return new ApiResponse<>(true,m,d);} public static <T> ApiResponse<T> error(String m){return new ApiResponse<>(false,m,null);} public boolean isSuccess(){return success;} public String getMessage(){return message;} public T getData(){return data;} public LocalDateTime getTimestamp(){return timestamp;}}
